"""Sample installment result over the standalone simple-interest loan engine."""
from engine.loan_payoff import plan_loan_payoff
from dashboard.simple_view import page,tile
from dashboard.report import text,money


def render(value):
    result=plan_loan_payoff(value)
    rows=''.join('<tr>'+''.join('<td>'+text(v)+'</td>' for v in (p.credited_at.strftime('%b %d, %Y'),
        p.source_account_id,money(p.fees_paid),money(p.interest_paid),money(p.principal_paid),money(p.total_paid),money(p.principal_remaining)))+'</tr>' for p in result.payments)
    return page('Sample loan payoff','<div class="hero"><span class="sample">Sample loan · Separate calculation</span><h1>See a loan reach zero.</h1><p>A $1,000 simple-interest loan with a 12% note rate, $100 contractual installments and a $150 payment target. Extra principal does not cancel future installments.</p></div>'+\
        '<div class="cards">'+tile('Loan paid off',str(result.payoff_date) if result.payoff_date else 'Not reached','Includes principal, interest and outstanding fees.')+tile('Interest paid',money(result.interest_paid),'Calculated from the note rate; the sample disclosed APR is different.')+tile('Total paid',money(result.total_paid),'Fees first, then interest, then principal.')+'</div><p>'+('All supplied minimum due dates were met.' if result.all_minimums_met else 'A minimum due date was missed: '+text(', '.join(map(str,result.missed_due_dates))))+'</p><section><h2>Dated loan payments</h2><div class="scroll"><table><thead><tr><th>Credited</th><th>Paid from</th><th>Fees</th><th>Interest</th><th>Principal</th><th>Total</th><th>Principal left</th></tr></thead><tbody>'+rows+'</tbody></table></div></section><section><h2>What this example assumes</h2><p>Simple daily interest using the 12% contractual note rate and a fixed 365-day divisor. Disclosed APR is 20% and is not substituted for the note rate. Accrual runs from the opening date up to each credit date; interest is rounded only at an actual payment. The final unpaid interval includes the ending day.</p><p>Explicit monthly due dates on the 20th. No future fees, rate changes or new borrowing. Payments initiate, credit, debit and settle on the same date. The loan uses principal curtailment; paid-ahead and precomputed contracts are refused without their actual schedules.</p><p>This loan calculation is not combined with a card payoff plan. Do not add the two plans together as if they share one budget. It is not a servicer payoff quote, and it does not use your Avant loan terms.</p></section><div class="actions"><a class="action secondary" download="loan-payoff-inputs.json" href="/loan-payoff-example/inputs.json">Download exact inputs</a><a class="action secondary" download="loan-payments.csv" href="/loan-payoff-example/payments.csv">Download payment schedule</a><a href="/">Home</a></div>')
